1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"syscall"
12	)
13	
14	// BuiltinVersionID identifies the built-in rule version, which reproduces
15	// the original fixed rules. It is always available, its parameters are
16	// queryable, and it cannot be overridden.
17	const BuiltinVersionID = "builtin"
18	
19	// ErrUnknownVersion reports a reference to a rule version that was never
20	// registered in the archive.
21	var ErrUnknownVersion = errors.New("unknown version")
22	
23	// ErrVersionConflict reports a re-registration of an existing version ID
24	// with different parameters.
25	var ErrVersionConflict = errors.New("version already registered with different parameters")
26	
27	// ErrCorruptVersion reports a version whose stored archive document no
28	// longer satisfies the registration rules: a rule object or a required
29	// field is missing or null, a value has the wrong type, or a severity or
30	// multiplier is out of range. The decoded struct cannot tell a missing
31	// field from an explicit zero value, so such an archive would otherwise
32	// compare under silently zeroed parameters (a zero displacement
33	// multiplier even crashes detection). A comparison naming a corrupt
34	// version is refused; the corrupt content is never replaced by the
35	// enabled version, the built-in rules or defaults.
36	var ErrCorruptVersion = errors.New("archived rule version is corrupted")
37	
38	// SandwichRule configures the sandwich rule: whether it runs and the
39	// severity of its conclusions.
40	type SandwichRule struct {
41		Enabled  bool `json:"enabled"`
42		Severity int  `json:"severity"`
43	}
44	
45	// DisplacementRule configures the displacement rule. A victim is flagged
46	// only when the previous swap's GasPrice strictly exceeds Multiplier times
47	// the victim's.
48	type DisplacementRule struct {
49		Enabled    bool `json:"enabled"`
50		Severity   int  `json:"severity"`
51		Multiplier int  `json:"multiplier"`
52	}
53	
54	// RuleSet is the complete declaration of both detection rules. Every
55	// version must declare both rules in full.
56	type RuleSet struct {
57		Sandwich     SandwichRule     `json:"sandwich"`
58		Displacement DisplacementRule `json:"displacement"`
59	}
60	
61	// RuleVersion is a named, immutable set of rule parameters.
62	type RuleVersion struct {
63		ID    string  `json:"id"`
64		Rules RuleSet `json:"rules"`
65	}
66	
67	// BuiltinVersion returns the version representing the original fixed
68	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
69	func BuiltinVersion() RuleVersion {
70		return RuleVersion{
71			ID: BuiltinVersionID,
72			Rules: RuleSet{
73				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
74				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
75			},
76		}
77	}
78	
79	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
80	// distinguish a missing field from an explicit zero value, and the decoder
81	// rejects unknown fields (including unknown rule names).
82	type toggleSpec struct {
83		Enabled  *bool `json:"enabled"`
84		Severity *int  `json:"severity"`
85	}
86	
87	type displacementSpec struct {
88		Enabled    *bool `json:"enabled"`
89		Severity   *int  `json:"severity"`
90		Multiplier *int  `json:"multiplier"`
91	}
92	
93	type versionSpec struct {
94		ID    *string `json:"id"`
95		Rules *struct {
96			Sandwich     *toggleSpec       `json:"sandwich"`
97			Displacement *displacementSpec `json:"displacement"`
98		} `json:"rules"`
99	}
100	
101	func parseEnabled(name string, v *bool) (bool, error) {
102		if v == nil {
103			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
104		}
105		return *v, nil
106	}
107	
108	func parseSeverity(name string, v *int) (int, error) {
109		if v == nil {
110			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
111		}
112		if *v < 1 || *v > 5 {
113			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
114		}
115		return *v, nil
116	}
117	
118	// ErrDuplicateField reports a JSON object in a registration spec that
119	// names the same field twice. Field names are compared the way JSON
120	// decoding matches struct fields, so two spellings the decoder folds
121	// together — differing only in case, like "severity" and "Severity", or
122	// using a compatibility character, like "ſeverity" (U+017F for s) — are
123	// also duplicates.
124	var ErrDuplicateField = errors.New("duplicate field in version spec")
125	
126	// ErrTrailingData reports non-whitespace content after the single JSON
127	// object that makes up a registration spec: a second object, another
128	// JSON value, an unmatched bracket or any other character.
129	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
130	
131	// versionScanPolicy validates the shape of a rule version document with
132	// the shared scanner while keeping version-spec wording and sentinel
133	// errors.
134	var versionScanPolicy = specPolicy{
135		topObject:          "version spec",
136		known:              versionFields,
137		nested:             versionNestedTables,
138		rejectExactUnknown: true,
139		firstTokenError: func(err error) error {
140			if errors.Is(err, io.EOF) {
141				return errors.New("version spec must be a JSON object, got empty input")
142			}
143			return fmt.Errorf("invalid version spec: %w", err)
144		},
145		nonObject: func(tok json.Token) error {
146			if tok == nil {
147				return errors.New("version spec must be a JSON object, got null")
148			}
149			if d, ok := tok.(json.Delim); ok && d == '[' {
150				return errors.New("version spec must be a single JSON object, got array")
151			}
152			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
153		},
154		wrap: func(err error) error {
155			return fmt.Errorf("invalid version spec: %w", err)
156		},
157		duplicate: func(obj, field, first, _ string) error {
158			return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
159		},
160		trailing: versionTrailingData,
161	}
162	
163	// validateSpecStructure proves raw contains exactly one JSON object with
164	// no repeated fields anywhere in it, and nothing but whitespace around
165	// it. Keys are matched against the known fields of the version, rules,
166	// sandwich and displacement objects with the decoder's own field-name
167	// folding: "SEVERITY", "severity" and "ſeverity" (U+017F for s) all point
168	// at the same field and cannot share one object. Escaped key spellings
169	// are decoded before comparison, so "severity" cannot evade it.
170	func validateSpecStructure(raw []byte) error {
171		return scanJSONObject(raw, versionScanPolicy)
172	}
173	
174	// versionTrailingData names the first non-whitespace byte after the
175	// closed object, so an unmatched '}' or ']' is reported directly rather
176	// than as a syntax error; only whitespace may follow the object.
177	func versionTrailingData(raw []byte, offset int) error {
178		rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
179		if len(rest) > 0 {
180			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
181		}
182		return nil
183	}
184	
185	var (
186		versionFields       = fieldTable("id", "rules")
187		rulesFields         = fieldTable("sandwich", "displacement")
188		sandwichFields      = fieldTable("enabled", "severity")
189		displacementFields  = fieldTable("enabled", "severity", "multiplier")
190		versionNestedTables = map[string]nestedObjectSpec{
191			"rules":        {rulesFields, "rules object"},
192			"sandwich":     {sandwichFields, "rules.sandwich"},
193			"displacement": {displacementFields, "rules.displacement"},
194		}
195	)
196	
197	// ParseRuleVersion validates a registration document. It must contain
198	// exactly one complete JSON object (leading and trailing whitespace
199	// allowed): a second object or value, an unmatched bracket or any other
200	// trailing character fails, and empty input, arrays and null are not
201	// specs. Duplicate fields are rejected at the top level, in rules and in
202	// each rule's parameters, including any spellings the decoder folds onto
203	// the same known field (case variants, U+017F for s, and the like). Missing fields, wrong types, out-of-range values and unknown
204	// rules or fields all fail with a reason.
205	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
206		if err := validateSpecStructure(raw); err != nil {
207			return RuleVersion{}, err
208		}
209		var spec versionSpec
210		dec := json.NewDecoder(bytes.NewReader(raw))
211		dec.DisallowUnknownFields()
212		if err := dec.Decode(&spec); err != nil {
213			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
214		}
215		if spec.ID == nil || *spec.ID == "" {
216			return RuleVersion{}, errors.New("id must be a non-empty string")
217		}
218		if spec.Rules == nil {
219			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
220		}
221		if spec.Rules.Sandwich == nil {
222			return RuleVersion{}, errors.New("rules.sandwich is required")
223		}
224		if spec.Rules.Displacement == nil {
225			return RuleVersion{}, errors.New("rules.displacement is required")
226		}
227		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
228		if err != nil {
229			return RuleVersion{}, err
230		}
231		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
232		if err != nil {
233			return RuleVersion{}, err
234		}
235		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
236		if err != nil {
237			return RuleVersion{}, err
238		}
239		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
240		if err != nil {
241			return RuleVersion{}, err
242		}
243		mult := spec.Rules.Displacement.Multiplier
244		if mult == nil {
245			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
246		}
247		if *mult < 2 || *mult > 100 {
248			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
249		}
250		return RuleVersion{
251			ID: *spec.ID,
252			Rules: RuleSet{
253				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
254				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
255			},
256		}, nil
257	}
258	
259	// findVersion resolves id against the built-in version and the archive's
260	// registered versions.
261	func findVersion(data archiveData, id string) (RuleVersion, error) {
262		if id == BuiltinVersionID {
263			return BuiltinVersion(), nil
264		}
265		for _, v := range data.Versions {
266			if v.ID == id {
267				return v, nil
268			}
269		}
270		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
271	}
272	
273	// intactVersion resolves id for a comparison and proves the version's
274	// stored archive document still satisfies every registration rule,
275	// re-validating the raw document with the same parser registrations pass.
276	// The decoded struct cannot do this: a missing enabled, severity or
277	// multiplier field unmarshals as the zero value and is indistinguishable
278	// from an explicitly declared one, and a wrong-typed field fails the
279	// whole-archive decode before any judgment can run. An explicitly
280	// declared false or any in-range value is valid; a missing or null field,
281	// a wrong type or an out-of-range number makes the version corrupt, and
282	// the failure names the version and the offending rule or field. The
283	// built-in version is constructed in code and always intact.
284	func intactVersion(versions []json.RawMessage, id string) (RuleVersion, error) {
285		if id == BuiltinVersionID {
286			return BuiltinVersion(), nil
287		}
288		for _, entry := range versions {
289			var meta struct {
290				ID string `json:"id"`
291			}
292			if err := json.Unmarshal(entry, &meta); err != nil || meta.ID != id {
293				continue
294			}
295			v, err := ParseRuleVersion(entry)
296			if err != nil {
297				return RuleVersion{}, fmt.Errorf("%w: %s: %w", ErrCorruptVersion, id, err)
298			}
299			return v, nil
300		}
301		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
302	}
303	
304	// enabledVersion resolves the archive's currently enabled version. Archives
305	// written before rule versions existed have no marker and run the built-in
306	// rules.
307	func (d archiveData) enabledVersion() (RuleVersion, error) {
308		if d.EnabledVersion == "" {
309			return BuiltinVersion(), nil
310		}
311		return findVersion(d, d.EnabledVersion)
312	}
313	
314	// RegisterVersion validates raw as a rule version spec and stores it in the
315	// archive at dir. Re-registering the same ID with identical parameters
316	// succeeds without adding a version (created is false); the same ID with
317	// different parameters is rejected. The built-in version ID is reserved.
318	// Any failure leaves the archive untouched.
319	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
320		v, err = ParseRuleVersion(raw)
321		if err != nil {
322			return RuleVersion{}, false, err
323		}
324		if v.ID == BuiltinVersionID {
325			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
326		}
327		if err := os.MkdirAll(dir, 0o755); err != nil {
328			return RuleVersion{}, false, err
329		}
330		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
331		if err != nil {
332			return RuleVersion{}, false, err
333		}
334		defer lock.Close()
335	
336		data, err := readArchive(dir)
337		if err != nil {
338			return RuleVersion{}, false, err
339		}
340		for _, existing := range data.Versions {
341			if existing.ID == v.ID {
342				if existing.Rules == v.Rules {
343					return existing, false, nil
344				}
345				return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
346			}
347		}
348		data.Versions = append(data.Versions, v)
349		if err := writeArchiveAtomic(dir, data); err != nil {
350			return RuleVersion{}, false, err
351		}
352		return v, true, nil
353	}
354	
355	// EnableVersion makes id the archive's active version for later replays.
356	// Enabling an unknown version fails and leaves the current enabled version
357	// unchanged.
358	func EnableVersion(dir, id string) (RuleVersion, error) {
359		if id == "" {
360			return RuleVersion{}, errors.New("version id must not be empty")
361		}
362		if err := os.MkdirAll(dir, 0o755); err != nil {
363			return RuleVersion{}, err
364		}
365		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
366		if err != nil {
367			return RuleVersion{}, err
368		}
369		defer lock.Close()
370	
371		data, err := readArchive(dir)
372		if err != nil {
373			return RuleVersion{}, err
374		}
375		v, err := findVersion(data, id)
376		if err != nil {
377			return RuleVersion{}, err
378		}
379		if data.EnabledVersion == id {
380			return v, nil
381		}
382		data.EnabledVersion = id
383		if err := writeArchiveAtomic(dir, data); err != nil {
384			return RuleVersion{}, err
385		}
386		return v, nil
387	}
388	
389	// ListVersions returns the built-in version plus every version registered
390	// in the archive, along with the currently enabled version ID.
391	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
392		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
393			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
394		}
395		lock, err := lockArchive(dir, syscall.LOCK_SH)
396		if err != nil {
397			return nil, "", err
398		}
399		defer lock.Close()
400	
401		data, err := readArchive(dir)
402		if err != nil {
403			return nil, "", err
404		}
405		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
406		enabled = data.EnabledVersion
407		if enabled == "" {
408			enabled = BuiltinVersionID
409		}
410		return versions, enabled, nil
411	}
412	
413	// GetVersion returns one version's full parameters by ID.
414	func GetVersion(dir, id string) (RuleVersion, error) {
415		if id == BuiltinVersionID {
416			return BuiltinVersion(), nil
417		}
418		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
419			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
420		}
421		lock, err := lockArchive(dir, syscall.LOCK_SH)
422		if err != nil {
423			return RuleVersion{}, err
424		}
425		defer lock.Close()
426	
427		data, err := readArchive(dir)
428		if err != nil {
429			return RuleVersion{}, err
430		}
431		return findVersion(data, id)
432	}
433	
434	// FindingChange pairs the archived and compared conclusions for one
435	// transaction whose kind or severity differs between the two versions.
436	type FindingChange struct {
437		TxHash   string        `json:"txHash"`
438		Original ReportFinding `json:"original"`
439		Compared ReportFinding `json:"compared"`
440	}
441	
442	// CompareResult is the outcome of re-judging one archived block under a
443	// different rule version. It carries both versions' parameters, both full
444	// conclusion sets, the raw swap evidence, and the per-transaction diff.
445	type CompareResult struct {
446		ChainID          string          `json:"chainId"`
447		BlockHash        string          `json:"blockHash"`
448		BlockNumber      int64           `json:"blockNumber"`
449		OriginalVersion  RuleVersion     `json:"originalVersion"`
450		ComparedVersion  RuleVersion     `json:"comparedVersion"`
451		OriginalFindings []ReportFinding `json:"originalFindings"`
452		ComparedFindings []ReportFinding `json:"comparedFindings"`
453		Swaps            []Swap          `json:"swaps"`
454		Added            []ReportFinding `json:"added"`
455		Removed          []ReportFinding `json:"removed"`
456		Changed          []FindingChange `json:"changed"`
457	}
458	
459	// compareArchiveDoc mirrors the archive file the way a comparison reads
460	// it: records fully decoded, but each registered version kept as its raw
461	// stored document. A corrupt version entry — a wrong-typed field, say —
462	// then cannot break the read or masquerade as whole-archive corruption;
463	// it is judged on its own by intactVersion.
464	type compareArchiveDoc struct {
465		Records  []record          `json:"records"`
466		Versions []json.RawMessage `json:"versions"`
467	}
468	
469	// Compare re-runs detection for one archived block under the given
470	// registered version and diffs the conclusions against the archived
471	// report. It only reads the archive: the original input file is not
472	// needed, and neither the archived report nor the enabled version is
473	// modified. The named version's stored document must still satisfy the
474	// registration rules in full; a corrupt one fails with ErrCorruptVersion
475	// rather than comparing under zeroed or substituted parameters.
476	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
477		if _, err := os.Stat(dir); err != nil {
478			if errors.Is(err, os.ErrNotExist) {
479				return CompareResult{}, ErrUnknownBlock
480			}
481			return CompareResult{}, err
482		}
483		lock, err := lockArchive(dir, syscall.LOCK_SH)
484		if err != nil {
485			return CompareResult{}, err
486		}
487		defer lock.Close()
488	
489		raw, err := readArchiveBytes(dir)
490		if err != nil {
491			return CompareResult{}, err
492		}
493		var doc compareArchiveDoc
494		if len(raw) > 0 {
495			if err := json.Unmarshal(raw, &doc); err != nil {
496				return CompareResult{}, fmt.Errorf("archive is corrupted: %w", err)
497			}
498		}
499		var rec *record
500		for i := range doc.Records {
501			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
502				rec = &doc.Records[i]
503				break
504			}
505		}
506		if rec == nil {
507			return CompareResult{}, ErrUnknownBlock
508		}
509		// The requested version must be intact in the archive: re-validate its
510		// stored document before judging anything, so a corrupt version fails
511		// the same way even when the block has no swaps and detection would
512		// produce no conclusions at all.
513		compared, err := intactVersion(doc.Versions, versionID)
514		if err != nil {
515			return CompareResult{}, err
516		}
517		original := rec.Findings
518		if original == nil {
519			original = []ReportFinding{}
520		}
521		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
522		swaps := rec.Swaps
523		if swaps == nil {
524			swaps = []Swap{}
525		}
526	
527		origByTx := make(map[string]ReportFinding, len(original))
528		for _, f := range original {
529			origByTx[f.TxHash] = f
530		}
531		compByTx := make(map[string]ReportFinding, len(rejudged))
532		for _, f := range rejudged {
533			compByTx[f.TxHash] = f
534		}
535		added := []ReportFinding{}
536		removed := []ReportFinding{}
537		changed := []FindingChange{}
538		for _, f := range rejudged {
539			if o, ok := origByTx[f.TxHash]; ok {
540				// A transaction present on both sides with a different kind or
541				// severity is a change, never an add plus a remove.
542				if o.Kind != f.Kind || o.Severity != f.Severity {
543					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
544				}
545			} else {
546				added = append(added, f)
547			}
548		}
549		for _, f := range original {
550			if _, ok := compByTx[f.TxHash]; !ok {
551				removed = append(removed, f)
552			}
553		}
554		byTx := func(fs []ReportFinding) {
555			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
556		}
557		byTx(added)
558		byTx(removed)
559		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
560	
561		return CompareResult{
562			ChainID:          rec.ChainID,
563			BlockHash:        rec.BlockHash,
564			BlockNumber:      rec.BlockNumber,
565			OriginalVersion:  rec.ruleVersion(),
566			ComparedVersion:  compared,
567			OriginalFindings: original,
568			ComparedFindings: rejudged,
569			Swaps:            swaps,
570			Added:            added,
571			Removed:          removed,
572			Changed:          changed,
573		}, nil
574	}
575

