568	// contenderStatuses gives each racing submitter a status of its own; the
569	// winner revision can then be proven to carry one submitter's complete
570	// content with no fields mixed in from another contender.
571	var contenderStatuses = []string{
572		ReviewStatusFalsePositive,
573		ReviewStatusReal,
574		ReviewStatusUnreviewed,
575	}
576	
577	func raceSub(i int) ReviewSubmission {
578		return reviewSub("1", "0xa", "0xv", "sandwich",
579			fmt.Sprintf("race-%02d", i),
580			fmt.Sprintf("operator-%02d", i),
581			fmt.Sprintf("reason-%02d", i),
582			contenderStatuses[i%len(contenderStatuses)], 1)
583	}
584	
585	type raceOutcome struct {
586		res SubmitReviewResult
587		err error
588	}
589	
590	// runRejudgmentRace fires n contenders carrying the same valid
591	// expectedVersion (1, against an object already at version 1) at the same
592	// instant, each with a distinct submissionId/operator/reason/status, and
593	// returns the per-submitter outcomes in submission order.
594	func runRejudgmentRace(t *testing.T, dir string, n int) []raceOutcome {
595		t.Helper()
596		outcomes := make([]raceOutcome, n)
597		var wg sync.WaitGroup
598		start := make(chan struct{})
599		for i := 0; i < n; i++ {
600			wg.Add(1)
601			go func(i int) {
602				defer wg.Done()
603				<-start
604				outcomes[i].res, outcomes[i].err = SubmitReview(dir, raceSub(i))
605			}(i)
606		}
607		close(start)
608		wg.Wait()
609		return outcomes
610	}
611	
612	// verifyRaceSettlement proves the anti-overwrite rules against the history
613	// actually persisted after a rejudgment race: exactly one contender created
614	// a revision, the object advanced exactly one version, every stored bit of
615	// the new revision comes from that winner alone, the original revision and
616	// the archived conclusion/evidence are untouched, and every loser (busy or
617	// version conflict) left no content behind.
618	func verifyRaceSettlement(t *testing.T, dir string, outcomes []raceOutcome, original ReviewRevision) int {
619		t.Helper()
620		winner := -1
621		busyIdx, conflictIdx := -1, -1
622		for i, o := range outcomes {
623			switch {
624			case o.err == nil:
625				if !o.res.Created || o.res.Version != 2 {
626					t.Fatalf("submitter %d returned %+v, want created at version 2", i, o.res)
627				}
628				if winner != -1 {
629					t.Fatalf("two successful contenders: %d and %d", winner, i)
630				}
631				winner = i
632			case errors.Is(o.err, ErrBusy):
633				// The contender hit the lock while another submitter held it.
634				busyIdx = i
635			case errors.Is(o.err, ErrReviewConflict):
636				// The contender entered after the lock was released, read the
637				// already-bumped version and was rejected on the version check.
638				conflictIdx = i
639			default:
640				t.Fatalf("submitter %d got an outcome other than success/busy/conflict: %v", i, o.err)
641			}
642		}
643		if winner == -1 {
644			t.Fatal("no contender succeeded")
645		}
646		t.Logf("race settled: winner=%d, busy=%d, version-conflict=%d (either loser outcome is valid)",
647			winner, countOutcomes(outcomes, ErrBusy), countOutcomes(outcomes, ErrReviewConflict))
648	
649		winSub := raceSub(winner)
650		wantRev := winSub.revision(2)
651		if !reflect.DeepEqual(outcomes[winner].res.Revision, wantRev) {
652			t.Fatalf("winner result revision = %+v, want %+v", outcomes[winner].res.Revision, wantRev)
653		}
654	
655		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
656		if err != nil {
657			t.Fatal(err)
658		}
659		if hist.Version != 2 || hist.Status != winSub.Status {
660			t.Fatalf("current state = %q/%d, want %q/2 (the winner's rejudgment)",
661				hist.Status, hist.Version, winSub.Status)
662		}
663		if len(hist.Revisions) != 2 {
664			t.Fatalf("object holds %d revisions, want exactly 2 (losers must leave none): %+v",
665				len(hist.Revisions), hist.Revisions)
666		}
667		if !reflect.DeepEqual(hist.Revisions[0], original) {
668			t.Fatalf("original revision not retained first: %+v, want %+v", hist.Revisions[0], original)
669		}
670		if !reflect.DeepEqual(hist.Revisions[1], wantRev) {
671			t.Fatalf("appended revision = %+v, want the winner's %+v", hist.Revisions[1], wantRev)
672		}
673		// Defense in depth: no field of any loser may appear in the new
674		// revision, and no loser submission id may be stored anywhere. Status is
675		// deliberately excluded because only three legal statuses exist so two
676		// contenders may legitimately carry the same one; identity/operator/
677		// reason are unique per submitter and the full-revision DeepEqual above
678		// already pins the winner's status.
679		loserIDs := map[string]bool{}
680		for i := range outcomes {
681			if i == winner {
682				continue
683			}
684			s := raceSub(i)
685			loserIDs[s.SubmissionID] = true
686			stored := hist.Revisions[1]
687			if stored.SubmissionID == s.SubmissionID || stored.Operator == s.Operator ||
688				stored.Reason == s.Reason {
689				t.Fatalf("loser %d content mixed into the stored revision: %+v", i, stored)
690			}
691			if reflect.DeepEqual(stored, s.revision(2)) {
692				t.Fatalf("stored revision is identical to loser %d's content: %+v", i, stored)
693			}
694		}
695		for _, rev := range hist.Revisions {
696			if loserIDs[rev.SubmissionID] {
697				t.Fatalf("loser submission id %q left a revision", rev.SubmissionID)
698			}
699		}
700		// The original archived conclusion, its detection parameters and the
701		// raw swap evidence stay exactly as archived.
702		if hist.Original == nil ||
703			hist.Original.Finding.TxHash != "0xv" || hist.Original.Finding.Kind != "sandwich" ||
704			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
705			t.Fatalf("original conclusion/evidence changed: %+v", hist.Original)
706		}
707		if hist.Original.Version.ID != BuiltinVersionID {
708			t.Fatalf("detection version changed: %+v", hist.Original.Version)
709		}
710	
711		// After the race, resubmitting with the stale expected version must be a
712		// version conflict regardless of how the contender originally lost: a
713		// busy loss is not a completed rejudgment, and neither path may overwrite
714		// the winner.
715		recheck := func(idx int, label string) {
716			if idx < 0 {
717				return
718			}
719			if _, err := SubmitReview(dir, raceSub(idx)); !errors.Is(err, ErrReviewConflict) {
720				t.Fatalf("%s loser (submitter %d) replayed with original expected version: got %v, want ErrReviewConflict",
721					label, idx, err)
722			}
723		}
724		recheck(busyIdx, "busy")
725		recheck(conflictIdx, "conflict")
726		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
727			t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
728		}
729	
730		// Deterministic late entrants: sequential submissions issued only after
731		// the object is provably at version 2 and the race lock is long released.
732		// Each acquires the free lock, reads the already-bumped version and must
733		// take the version-conflict path (never busy, since submissions are
734		// serialized here). This is the legitimate loser outcome the old
735		// regression assumed could never happen, and it must append nothing.
736		const lateN = 6
737		for j := 0; j < lateN; j++ {
738			_, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
739				fmt.Sprintf("late-%02d", j),
740				fmt.Sprintf("late-operator-%02d", j),
741				fmt.Sprintf("late-reason-%02d", j),
742				contenderStatuses[j%len(contenderStatuses)], 1))
743			if !errors.Is(err, ErrReviewConflict) {
744				t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
745			}
746		}
747	
748		// The follow-up conflict submissions appended nothing either.
749		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
750		if err != nil {
751			t.Fatal(err)
752		}
753		if final.Version != 2 || len(final.Revisions) != 2 || !reflect.DeepEqual(final.Revisions, hist.Revisions) {
754			t.Fatalf("post-race conflict replays changed history: %+v", final)
755		}
756		return winner
757	}
758	
759	func countOutcomes(outcomes []raceOutcome, target error) int {
760		n := 0
761		for _, o := range outcomes {
762			if errors.Is(o.err, target) {
763				n++
764			}
765		}
766		return n
767	}
768	
769	func TestSubmitReviewConcurrentRejudgmentSettlesOnce(t *testing.T) {
770		// Repeated races make the regression independent of scheduling: whether a
771		// contender hits the held lock or enters after release and loses on the
772		// version check, the settled history must be identical in shape. The loop
773		// is deterministic (no timing assumptions): every contender starts from a
774		// barrier and the settled state is derived from stored data, not from how
775		// many contenders reported busy versus conflict.
776		const racers, iterations = 12, 25
777		for iter := 0; iter < iterations; iter++ {
778			dir := t.TempDir()
779			mustReplay(t, dir, twoFindingsInput)
780			// An object that already carries one real risk judgment: the race is
781			// a concurrent rejudgment at expectedVersion 1, not a first submit.
782			first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-0", "alice", "first real call", ReviewStatusReal, 0))
783			if !first.Created || first.Version != 1 {
784				t.Fatalf("iter %d setup = %+v", iter, first)
785			}
786			outcomes := runRejudgmentRace(t, dir, racers)
787			verifyRaceSettlement(t, dir, outcomes, first.Revision)
788		}
789	}
790	
791	// TestSubmitReviewBusyHoldsOffThenActualVersionDecides pins the two-phase
792	// behavior deterministically (without relying on goroutine interleaving):
793	// while the archive is occupied, a valid rejudgment returns busy and changes
794	// nothing; once the lock is released the same submission is accepted or
795	// rejected by the object's actual version, never because the busy attempt was
796	// treated as a completed rejudgment.
797	func TestSubmitReviewBusyHoldsOffThenActualVersionDecides(t *testing.T) {
798		dir := t.TempDir()
799		mustReplay(t, dir, twoFindingsInput)
800		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "hold-1", "alice", "confirmed bot war", ReviewStatusReal, 0))
801		if !first.Created || first.Version != 1 {
802			t.Fatalf("setup = %+v", first)
803		}
804		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
805		if err != nil {
806			t.Fatal(err)
807		}
808	
809		holder, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
810		if err != nil {
811			t.Fatal(err)
812		}
813		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_EX); err != nil {
814			t.Fatal(err)
815		}
816	
817		// A legal rejudgment based on version 1: while occupied it must report
818		// busy and write nothing.
819		contender := reviewSub("1", "0xa", "0xv", "sandwich", "hold-2", "bob", "second look says false positive", ReviewStatusFalsePositive, 1)
820		res, err := SubmitReview(dir, contender)
821		if !errors.Is(err, ErrBusy) {
822			t.Fatalf("occupied archive: got %v, want ErrBusy", err)
823		}
824		if res.Created || res.Version != 0 || res.Revision != (ReviewRevision{}) {
825			t.Fatalf("busy submission returned a non-empty result: %+v", res)
826		}
827		archiveDuring, err := os.ReadFile(filepath.Join(dir, archiveFileName))
828		if err != nil {
829			t.Fatal(err)
830		}
831		if !reflect.DeepEqual(archiveBefore, archiveDuring) {
832			t.Fatal("busy submission changed the archive while the lock was held")
833		}
834	
835		// Release the occupation; existing review content must be intact.
836		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_UN); err != nil {
837			t.Fatal(err)
838		}
839		if err := holder.Close(); err != nil {
840			t.Fatal(err)
841		}
842		held, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
843		if err != nil {
844			t.Fatal(err)
845		}
846		if held.Status != ReviewStatusReal || held.Version != 1 || len(held.Revisions) != 1 {
847			t.Fatalf("busy loss altered review content: %+v", held)
848		}
849		if !reflect.DeepEqual(held.Revisions[0], first.Revision) {
850			t.Fatalf("original revision changed: %+v, want %+v", held.Revisions[0], first.Revision)
851		}
852	
853		// Lock released but the object is still at version 1 (busy never
854		// completed the rejudgment): the same submission with its original
855		// expectedVersion 1 now succeeds as a fresh create — the busy attempt
856		// neither consumed the submission id nor counted as a stored revision.
857		retry, err := SubmitReview(dir, contender)
858		if err != nil {
859			t.Fatalf("retry after release: %v", err)
860		}
861		wantRev := contender.revision(2)
862		if !retry.Created || retry.Version != 2 || !reflect.DeepEqual(retry.Revision, wantRev) {
863			t.Fatalf("retry = %+v, want created at v2 with %+v", retry, wantRev)
864		}
865		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
866		if err != nil {
867			t.Fatal(err)
868		}
869		if hist.Status != ReviewStatusFalsePositive || hist.Version != 2 || len(hist.Revisions) != 2 {
870			t.Fatalf("object after retry = %q/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
871		}
872		if !reflect.DeepEqual(hist.Revisions[0], first.Revision) || !reflect.DeepEqual(hist.Revisions[1], wantRev) {
873			t.Fatalf("revisions after retry = %+v", hist.Revisions)
874		}
875	
876		// Independently, if another rejudgment had committed while we waited,
877		// releasing the lock would not make the stale submission succeed: with
878		// the object now at version 2, a version-1 submission conflicts and
879		// leaves no revision.
880		late := reviewSub("1", "0xa", "0xv", "sandwich", "hold-3", "carol", "late arrival", ReviewStatusUnreviewed, 1)
881		if _, err := SubmitReview(dir, late); !errors.Is(err, ErrReviewConflict) {
882			t.Fatalf("stale submission after release: got %v, want ErrReviewConflict", err)
883		}
884		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
885		if err != nil {
886			t.Fatal(err)
887		}
888		if after.Version != 2 || len(after.Revisions) != 2 || !reflect.DeepEqual(after.Revisions, hist.Revisions) {
889			t.Fatalf("post-release conflict appended a revision: %+v", after)
890		}
891	}
892	
893	func TestSubmitReviewFailureLeavesNoHalfRevision(t *testing.T) {
894		dir := t.TempDir()
895		mustReplay(t, dir, twoFindingsInput)
896		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
897		if err != nil {
898			t.Fatal(err)
899		}
900		// Unknown conclusion fails validation against archive content and must
901		// not append anything.
902		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xghost", "sandwich", "s", "a", "r", ReviewStatusReal, 0)); !errors.Is(err, ErrUnknownConclusion) {
903			t.Fatalf("got %v, want ErrUnknownConclusion", err)
904		}
905		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
906		if err != nil {
907			t.Fatal(err)
908		}
909		if !reflect.DeepEqual(before, after) {
910			t.Fatal("failed submission modified the archive")
911		}
912	}
913	
914	// breakArchiveSave makes the archive commit fail at the save stage: the
915	// temporary file the atomic writer creates becomes a directory, so opening
916	// it as a regular file fails while the lock, the archived conclusion, the
917	// review object and its revisions are all valid. This is a storage failure
918	// at persistence time, not a validation, version-conflict or busy error.
919	func breakArchiveSave(t *testing.T, dir string) {
920		t.Helper()
921		tmp := filepath.Join(dir, archiveFileName+".tmp")
922		if err := os.Mkdir(tmp, 0o755); err != nil {
923			t.Fatalf("break archive save: %v", err)
924		}
925	}
926	
927	func restoreArchiveSave(t *testing.T, dir string) {
928		t.Helper()
929		if err := os.RemoveAll(filepath.Join(dir, archiveFileName+".tmp")); err != nil {
930			t.Fatalf("restore archive save: %v", err)
931		}
932	}
933	
934	func TestSubmitReviewSaveFailureRetriedAfterRecovery(t *testing.T) {
935		dir := t.TempDir()
936		mustReplay(t, dir, twoFindingsInput)
937	
938		// A pre-existing alert record must survive the failed and successful
939		// submissions byte-for-byte in content.
940		alertsBefore, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
941		if err != nil {
942			t.Fatal(err)
943		}
944		if len(alertsBefore) != 2 {
945			t.Fatalf("setup: got %d alert records, want 2", len(alertsBefore))
946		}
947	
948		// Main precondition: the object is at version 1 with a real judgment and
949		// one complete revision.
950		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
951		if !first.Created || first.Version != 1 {
952			t.Fatalf("setup submission = %+v", first)
953		}
954	
955		original, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
956		if err != nil {
957			t.Fatal(err)
958		}
959		if original.Status != ReviewStatusReal || original.Version != 1 || len(original.Revisions) != 1 {
960			t.Fatalf("setup object state = %+v", original)
961		}
962		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
963		if err != nil {
964			t.Fatal(err)
965		}
966	
967		// Valid target, valid content, valid expected version: the only failure
968		// is storage failing while the new revision is being archived.
969		breakArchiveSave(t, dir)
970		rejudgment := reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually a false positive", ReviewStatusFalsePositive, 1)
971		failed, err := SubmitReview(dir, rejudgment)
972		if err == nil {
973			t.Fatalf("save failure must return an error, got result %+v", failed)
974		}
975		if errors.Is(err, ErrBusy) || errors.Is(err, ErrReviewConflict) ||
976			errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrSubmissionConflict) {
977			t.Fatalf("failure must happen at the save stage, got %v", err)
978		}
979		if failed.Created {
980			t.Fatalf("failed save must not report created=true: %+v", failed)
981		}
982		restoreArchiveSave(t, dir)
983	
984		// The original judgment is fully retained: still real at version 1, the
985		// single original revision with no trace of the failed submission.
986		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
987		if err != nil {
988			t.Fatal(err)
989		}
990		if after.Status != ReviewStatusReal || after.Version != 1 {
991			t.Fatalf("failed save advanced the object: %q/%d, want real/1", after.Status, after.Version)
992		}
993		if len(after.Revisions) != 1 {
994			t.Fatalf("failed save left %d revisions: %+v", len(after.Revisions), after.Revisions)
995		}
996		if !reflect.DeepEqual(after.Revisions[0], original.Revisions[0]) {
997			t.Fatalf("original revision changed: %+v, want %+v", after.Revisions[0], original.Revisions[0])
998		}
999		for _, rev := range after.Revisions {
1000			if rev.SubmissionID == "s-2" || rev.Operator == "bob" ||
1001				rev.Status == ReviewStatusFalsePositive || rev.Reason == "actually a false positive" {
1002				t.Fatalf("failed submission content leaked into history: %+v", rev)
1003			}
1004		}
1005		// The archived original conclusion, its detection version and the raw
1006		// swap evidence are untouched, as are the pre-existing alert records.
1007		if after.Original == nil ||
1008			after.Original.Finding.TxHash != "0xv" || after.Original.Finding.Kind != "sandwich" ||
1009			after.Original.Finding.Severity != 3 || len(after.Original.Finding.Evidence) != 3 {
1010			t.Fatalf("original conclusion/evidence changed: %+v", after.Original)
1011		}
1012		if after.Original.Version.ID != BuiltinVersionID {
1013			t.Fatalf("detection version changed: %+v", after.Original.Version)
1014		}
1015		archiveAfter, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1016		if err != nil {
1017			t.Fatal(err)
1018		}
1019		if !reflect.DeepEqual(archiveBefore, archiveAfter) {
1020			t.Fatal("failed save modified the archive file")
1021		}
1022		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
1023		if err != nil {
1024			t.Fatal(err)
1025		}
1026		if !reflect.DeepEqual(alertsBefore, alertsAfter) {
1027			t.Fatalf("alert records changed: before %+v after %+v", alertsBefore, alertsAfter)
1028		}
1029	
1030		// Storage recovered: the exact same submission, same submissionId and
1031		// still expectedVersion 1, goes through as a fresh create — the failed
1032		// attempt must neither have consumed the submission id nor count as a
1033		// stored duplicate.
1034		retry, err := SubmitReview(dir, rejudgment)
1035		if err != nil {
1036			t.Fatalf("retry after recovery: %v", err)
1037		}
1038		if !retry.Created || retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
1039			t.Fatalf("retry = %+v, want created=true at version 2", retry)
1040		}
1041		wantRev := rejudgment.revision(2)
1042		if !reflect.DeepEqual(retry.Revision, wantRev) {
1043			t.Fatalf("saved revision = %+v, want %+v", retry.Revision, wantRev)
1044		}
1045	
1046		saved, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1047		if err != nil {
1048			t.Fatal(err)
1049		}
1050		if saved.Status != ReviewStatusFalsePositive || saved.Version != 2 || len(saved.Revisions) != 2 {
1051			t.Fatalf("object after retry = %q/%d with %d revisions", saved.Status, saved.Version, len(saved.Revisions))
1052		}
1053		if !reflect.DeepEqual(saved.Revisions[0], original.Revisions[0]) {
1054			t.Fatalf("original revision not retained first: %+v", saved.Revisions[0])
1055		}
1056		if !reflect.DeepEqual(saved.Revisions[1], wantRev) {
1057			t.Fatalf("appended revision = %+v, want %+v", saved.Revisions[1], wantRev)
1058		}
1059	
1060		// Sending the now-successful submission verbatim a second time is the
1061		// ordinary idempotent retry: created:false, the first successfully saved
1062		// revision returned, history unchanged.
1063		again, err := SubmitReview(dir, rejudgment)
1064		if err != nil {
1065			t.Fatalf("verbatim resend: %v", err)
1066		}
1067		if again.Created {
1068			t.Fatal("verbatim resend of a stored submission must report created=false")
1069		}
1070		if !reflect.DeepEqual(again.Revision, wantRev) || again.Version != 2 || again.Status != ReviewStatusFalsePositive {
1071			t.Fatalf("resend result = %+v", again)
1072		}
1073		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1074		if err != nil {
1075			t.Fatal(err)
1076		}
1077		if final.Version != 2 || len(final.Revisions) != 2 {
1078			t.Fatalf("verbatim resend changed history: version %d, %d revisions", final.Version, len(final.Revisions))
1079		}
1080		if !reflect.DeepEqual(final.Revisions, saved.Revisions) {
1081			t.Fatalf("verbatim resend appended a revision: %+v", final.Revisions)
1082		}
1083	}
