25		// multiplier 3.
26		archivedVersionSpec = `{"id":"archA","rules":{"sandwich":{"enabled":true,"severity":4},"displacement":{"enabled":true,"severity":1,"multiplier":3}}}`
27		// enabledVersion is enabled in the archive afterwards but must never
28		// leak into either side of a comparison. Its judgments are markedly
29		// different: sandwich severity 5, displacement severity 5 with
30		// multiplier 4.
31		enabledVersionSpec = `{"id":"liveB","rules":{"sandwich":{"enabled":true,"severity":5},"displacement":{"enabled":true,"severity":5,"multiplier":4}}}`
32		// candidateVersion is the version named at compare time: sandwich
33		// disabled, displacement severity 4 with the builtin multiplier 2.
34		candidateVersionSpec = `{"id":"candC","rules":{"sandwich":{"enabled":false,"severity":3},"displacement":{"enabled":true,"severity":4,"multiplier":2}}}`
35		// twinVersion carries the builtin parameters under another id, so a
36		// comparison produces identical conclusions and an empty diff.
37		twinVersionSpec = `{"id":"twin","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
38	)
