40	// cmpSwap builds one swap record map; In and Out are fixed because the
41	// detection rules never read them, while every numeric field is explicit.
42	func cmpSwap(tx, pool, trader string, gas int64, index int) map[string]any {
43		return map[string]any{
44			"TxHash": tx, "Pool": pool, "Trader": trader,
45			"In": 1, "Out": 1, "GasPrice": gas, "Index": index,
46		}
47	}
