60	// compareFixtureInput covers every diff shape in one archived block:
61	//
62	//	p1 0xa0f/0xa0v/0xa0b  sandwich sev4 under archA -> displacement sev4
63	//	                      under candC (kind change, severity identical);
64	//	p2 0xb0f/0xb0v/0xb0z  displacement sev1 (mult 3) -> sev4 (mult 2),
65	//	                      a severity-only change;
66	//	p3 0xc0f/0xc0v       no conclusion under either version, no diff;
67	//	p4 0xd0f/0xd0v       absent under archA (25 <= 30), displacement
68	//	                      sev4 under candC (25 > 20): added;
69	//	p5 0xe0f/0xe0v/0xe0b sandwich sev4 under archA (15/11 bracket 10),
70	//	                      nothing under candC (sandwich off, 15 <= 20):
71	//	                      removed.
72	func compareFixtureInput() string {
73		lines := []string{
74			cmpBlockLine("1", "0xblk", 100,
75				cmpSwap("0xa0f", "p1", "bot", 90, 0),
76				cmpSwap("0xa0v", "p1", "user", 10, 1),
77				cmpSwap("0xa0b", "p1", "bot", 80, 2),
78				cmpSwap("0xb0f", "p2", "w", 40, 3),
79				cmpSwap("0xb0v", "p2", "u", 10, 4),
80				cmpSwap("0xb0z", "p2", "z", 10, 5),
81				cmpSwap("0xc0f", "p3", "w", 15, 6),
82				cmpSwap("0xc0v", "p3", "u", 10, 7),
83				cmpSwap("0xd0f", "p4", "w", 25, 8),
84				cmpSwap("0xd0v", "p4", "u", 10, 9),
85				cmpSwap("0xe0f", "p5", "bot", 15, 10),
86				cmpSwap("0xe0v", "p5", "user", 10, 11),
87				cmpSwap("0xe0b", "p5", "bot", 11, 12),
88			),
89			// Decoy: same height, different block hash on the same chain.
90			cmpBlockLine("1", "0xother", 100,
91				cmpSwap("0xzz1", "pz", "tz", 999, 0),
92				cmpSwap("0xzz2", "pz", "tz2", 998, 1),
93			),
94			// Decoy: same height and hash on another chain.
95			cmpBlockLine("2", "0xblk", 100,
96				cmpSwap("0xqq1", "pq", "tq", 777, 0),
97				cmpSwap("0xqq2", "pq", "tq2", 776, 1),
98			),
99		}
100		return strings.Join(lines, "\n") + "\n"
101	}
