103	// setupCompareArchive writes the fixture to a real (then deleted) input
104	// file, archives it under archA, registers candC and enables liveB. The
105	// returned input path has already been removed, proving compare needs no
106	// source file.
107	func setupCompareArchive(t *testing.T) string {
108		t.Helper()
109		dir := t.TempDir()
110		inputPath := filepath.Join(t.TempDir(), "blocks.jsonl")
111		if err := os.WriteFile(inputPath, []byte(compareFixtureInput()), 0o644); err != nil {
112			t.Fatal(err)
113		}
114		register(t, dir, archivedVersionSpec)
115		register(t, dir, enabledVersionSpec)
116		register(t, dir, candidateVersionSpec)
117		register(t, dir, twinVersionSpec)
118		if reports, err := ReplayFileWithVersion(inputPath, dir, "archA"); err != nil {
119			t.Fatalf("ReplayFileWithVersion: %v", err)
120		} else if len(reports) != 3 {
121			t.Fatalf("got %d reports, want 3", len(reports))
122		}
123		if _, err := EnableVersion(dir, "liveB"); err != nil {
124			t.Fatalf("EnableVersion: %v", err)
125		}
126		if err := os.Remove(inputPath); err != nil {
127			t.Fatal(err)
128		}
129		return dir
130	}
