507			t.Fatal(err)
508		}
509		if other.ChainID != "1" || other.BlockHash != "0xother" || len(other.Swaps) != 2 {
510			t.Fatalf("same-height other block scoping wrong: %+v", other)
511		}
512		if chain2.ChainID != "2" || chain2.BlockHash != "0xblk" || len(chain2.Swaps) != 2 {
513			t.Fatalf("other-chain block scoping wrong: %+v", chain2)
514		}
515		if chain2.Swaps[0].TxHash != "0xqq1" || main.Swaps[0].TxHash != "0xa0f" {
516			t.Fatalf("swap records leaked across chains: main=%+v chain2=%+v", main.Swaps, chain2.Swaps)
517		}
518		// Findings from one identity never appear under another.
519		all := append(append([]ReportFinding{}, main.OriginalFindings...), other.OriginalFindings...)
520		all = append(all, chain2.OriginalFindings...)
521		for _, f := range all {
522			if strings.HasPrefix(f.TxHash, "0xzz") || strings.HasPrefix(f.TxHash, "0xqq") {
523				t.Fatalf("decoy conclusion leaked into another block's set: %+v", all)
524			}
525		}
526		// Determinism: repeated queries produce identical JSON.
527		again, err := Compare(dir, "1", "0xblk", "candC")
528		if err != nil {
529			t.Fatal(err)
530		}
531		b1, _ := json.Marshal(main)
532		b2, _ := json.Marshal(again)
533		if string(b1) != string(b2) {
534			t.Fatalf("compare is not deterministic:\n%s\n%s", b1, b2)
535		}
536		// Sanity: findings inside each result stay severity desc / hash asc.
537		for _, r := range []CompareResult{main, other, chain2} {
538			if !sort.SliceIsSorted(r.OriginalFindings, func(i, j int) bool {
539				a, b := r.OriginalFindings[i], r.OriginalFindings[j]
540				if a.Severity != b.Severity {
541					return a.Severity > b.Severity
542				}
543				return a.TxHash < b.TxHash
544			}) {
545				t.Fatalf("original findings not severity/hash ordered: %+v", r.OriginalFindings)
546			}
547		}
548	}
549	
550	// rewriteStoredVersion rewrites the stored archive document of the
551	// registered version id through mutate, simulating an archive whose
552	// registered version no longer satisfies the registration rules even
553	// though the file is still valid JSON.
554	func rewriteStoredVersion(t *testing.T, dir, id string, mutate func(ver map[string]any)) {
555		t.Helper()
556		path := filepath.Join(dir, archiveFileName)
557		raw, err := os.ReadFile(path)
558		if err != nil {
559			t.Fatal(err)
560		}
561		var doc map[string]any
562		if err := json.Unmarshal(raw, &doc); err != nil {
563			t.Fatal(err)
564		}
565		versions, ok := doc["versions"].([]any)
566		if !ok {
567			t.Fatalf("no versions array in archive: %s", raw)
568		}
569		found := false
570		for _, entry := range versions {
571			ver, ok := entry.(map[string]any)
572			if !ok || ver["id"] != id {
573				continue
574			}
575			mutate(ver)
576			found = true
577		}
578		if !found {
579			t.Fatalf("version %s not stored in archive", id)
580		}
581		out, err := json.MarshalIndent(doc, "", "  ")
582		if err != nil {
583			t.Fatal(err)
584		}
585		if err := os.WriteFile(path, out, 0o644); err != nil {
586			t.Fatal(err)
587		}
588	}
589	
590	// storedRule navigates to one rule object inside a stored version
591	// document.
592	func storedRule(t *testing.T, ver map[string]any, name string) map[string]any {
593		t.Helper()
594		rules, ok := ver["rules"].(map[string]any)
595		if !ok {
596			t.Fatalf("stored version has no rules object: %v", ver)
597		}
598		rule, ok := rules[name].(map[string]any)
599		if !ok {
600			t.Fatalf("stored version has no rules.%s object: %v", name, ver)
601		}
602		return rule
603	}
604	
605	// setupCorruptCompareArchive registers candC (sandwich off, displacement
606	// severity 4 multiplier 2) and twin, and archives one block under candC
607	// whose adjacent same-pool swaps hit displacement with no sandwich — the
608	// exact shape that crashed detection when the stored multiplier decayed
609	// to zero.
610	func setupCorruptCompareArchive(t *testing.T) string {
611		t.Helper()
612		dir := t.TempDir()
613		register(t, dir, candidateVersionSpec)
614		register(t, dir, twinVersionSpec)
615		input := cmpBlockLine("1", "0xblk", 7,
616			cmpSwap("0xf", "p1", "w", 40, 0),
617			cmpSwap("0xv", "p1", "u", 10, 1),
618		)
619		if _, err := ReplayWithVersion(strings.NewReader(input), dir, "candC"); err != nil {
620			t.Fatal(err)
621		}
622		return dir
623	}
624	
625	func TestCompareCorruptVersionRefused(t *testing.T) {
626		corruptions := []struct {
627			name    string
628			mutate  func(t *testing.T, ver map[string]any)
629			wantErr string
630		}{
631			{"multiplier missing", func(t *testing.T, v map[string]any) {
632				delete(storedRule(t, v, "displacement"), "multiplier")
633			}, "multiplier"},
634			{"multiplier zero", func(t *testing.T, v map[string]any) {
635				storedRule(t, v, "displacement")["multiplier"] = 0
636			}, "multiplier"},
637			{"multiplier below range", func(t *testing.T, v map[string]any) {
638				storedRule(t, v, "displacement")["multiplier"] = 1
639			}, "multiplier"},
640			{"multiplier above range", func(t *testing.T, v map[string]any) {
641				storedRule(t, v, "displacement")["multiplier"] = 101
642			}, "multiplier"},
643			{"multiplier null", func(t *testing.T, v map[string]any) {
644				storedRule(t, v, "displacement")["multiplier"] = nil
645			}, "multiplier"},
646			{"multiplier wrong type", func(t *testing.T, v map[string]any) {
647				storedRule(t, v, "displacement")["multiplier"] = "2"
648			}, "multiplier"},
649			{"displacement severity missing", func(t *testing.T, v map[string]any) {
650				delete(storedRule(t, v, "displacement"), "severity")
651			}, "severity"},
652			{"displacement severity zero", func(t *testing.T, v map[string]any) {
653				storedRule(t, v, "displacement")["severity"] = 0
654			}, "severity"},
655			{"displacement severity above range", func(t *testing.T, v map[string]any) {
656				storedRule(t, v, "displacement")["severity"] = 6
657			}, "severity"},
658			{"displacement enabled missing", func(t *testing.T, v map[string]any) {
659				delete(storedRule(t, v, "displacement"), "enabled")
660			}, "enabled"},
661			// The sandwich rule is disabled in candC, but a disabled rule must
662			// still declare complete, in-range parameters.
663			{"disabled sandwich severity zero", func(t *testing.T, v map[string]any) {
664				storedRule(t, v, "sandwich")["severity"] = 0
665			}, "severity"},
666			{"disabled sandwich enabled missing", func(t *testing.T, v map[string]any) {
667				delete(storedRule(t, v, "sandwich"), "enabled")
668			}, "enabled"},
669			{"sandwich object missing", func(t *testing.T, v map[string]any) {
670				delete(v["rules"].(map[string]any), "sandwich")
671			}, "sandwich"},
672			{"displacement object missing", func(t *testing.T, v map[string]any) {
673				delete(v["rules"].(map[string]any), "displacement")
674			}, "displacement"},
675			{"rules object missing", func(t *testing.T, v map[string]any) {
676				delete(v, "rules")
677			}, "rules"},
678		}
679		for _, tc := range corruptions {
680			t.Run(tc.name, func(t *testing.T) {
681				dir := setupCorruptCompareArchive(t)
682				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
683					tc.mutate(t, ver)
684				})
685				_, err := Compare(dir, "1", "0xblk", "candC")
686				if err == nil {
687					t.Fatalf("corrupt version compared successfully")
688				}
689				if !errors.Is(err, ErrCorruptVersion) {
690					t.Fatalf("error = %v, want ErrCorruptVersion", err)
691				}
692				if errors.Is(err, ErrUnknownVersion) || errors.Is(err, ErrUnknownBlock) {
693					t.Fatalf("corruption misreported as unknown version/block: %v", err)
694				}
695				if !strings.Contains(err.Error(), "candC") {
696					t.Fatalf("error must name the requested version, got %v", err)
697				}
698				if !strings.Contains(err.Error(), tc.wantErr) {
699					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
700				}
701			})
702		}
703	}
704	
705	func TestCompareCorruptVersionEmptySwapsStillRefused(t *testing.T) {
706		dir := t.TempDir()
707		register(t, dir, candidateVersionSpec)
708		// A block with no swaps produces no conclusions under any version; the
709		// corrupt candidate must still be refused, not reported as an empty
710		// success.
711		input := `{"chainId":"1","blockHash":"0xempty","blockNumber":3,"swaps":[]}`
712		if _, err := ReplayWithVersion(strings.NewReader(input), dir, "candC"); err != nil {
713			t.Fatal(err)
714		}
715		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
716			delete(storedRule(t, ver, "displacement"), "multiplier")
717		})
718		_, err := Compare(dir, "1", "0xempty", "candC")
719		if !errors.Is(err, ErrCorruptVersion) {
720			t.Fatalf("error = %v, want ErrCorruptVersion", err)
721		}
722	}
723	
724	func TestCompareCorruptVersionDistinctFromUnknown(t *testing.T) {
725		dir := setupCorruptCompareArchive(t)
726		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
727			delete(storedRule(t, ver, "displacement"), "multiplier")
728		})
729	
730		// A version that was never registered stays an unknown-version
731		// failure, never a corruption one.
732		if _, err := Compare(dir, "1", "0xblk", "ghost"); !errors.Is(err, ErrUnknownVersion) ||
733			errors.Is(err, ErrCorruptVersion) {
734			t.Fatalf("unknown version error = %v", err)
735		}
736		// An unknown block stays an unknown-block failure.
737		if _, err := Compare(dir, "1", "0xghost", "candC"); !errors.Is(err, ErrUnknownBlock) {
738			t.Fatalf("unknown block error = %v", err)
739		}
740		// The corrupt sibling does not contaminate intact versions: comparing
741		// under twin or builtin still succeeds against the same archive.
742		for _, id := range []string{"twin", BuiltinVersionID} {
743			result, err := Compare(dir, "1", "0xblk", id)
744			if err != nil {
745				t.Fatalf("compare under intact %s failed: %v", id, err)
746			}
747			if len(result.ComparedFindings) != 1 || result.ComparedFindings[0].Kind != "displacement" {
748				t.Fatalf("compare under intact %s misjudged: %+v", id, result.ComparedFindings)
749			}
750		}
751	}
752	
753	func TestCompareCorruptVersionReadOnly(t *testing.T) {
754		dir := setupCorruptCompareArchive(t)
755		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
756			storedRule(t, ver, "displacement")["multiplier"] = 0
757		})
758		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
759		if err != nil {
760			t.Fatal(err)
761		}
762		if _, err := Compare(dir, "1", "0xblk", "candC"); !errors.Is(err, ErrCorruptVersion) {
763			t.Fatalf("error = %v, want ErrCorruptVersion", err)
764		}
765		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
766		if err != nil {
767			t.Fatal(err)
768		}
769		if !reflect.DeepEqual(before, after) {
770			t.Fatalf("failed compare against a corrupt version changed the archive")
771		}
772		// The archived report keeps its candC conclusions and parameters.
773		report, err := Query(dir, "1", "0xblk")
774		if err != nil {
775			t.Fatal(err)
776		}
777		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
778			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
779			t.Fatalf("archived report changed: %+v", report)
780		}
781	}
